import {addMedia,listMedia,getMedia,removeMedia,exportMedia,importMedia,clearMedia} from './modules/media.js';
import {atmospheres,applyAtmosphere,spaceTree,atmosphereOf} from './modules/atmosphere.js';
import {defaultLayout,panelTypes,resolveLayout,preview} from './modules/layout.js';
import {uid,loadPersistent,savePersistent,download,normalize,blank,listProjects,currentProjectId,createProject,renameProject,deleteProject,switchProject,flushSaves} from './modules/store.js';
import {cycles,descendant,esc} from './modules/logic.js';
let activeSpace='root';let state=await loadPersistent().catch(err=>{console.error("IndexedDB unavailable",err);alert("Storage unavailable: data may not persist. Export backups frequently.");return blank()}),tab='Home',selected=null,filter='',layoutTarget='preset',layoutSelection=null;const app=document.querySelector('#app');
let nexusZoom=1,nexusPan={x:0,y:0};let displayMode=localStorage.getItem('atlas-display-mode')||'auto';let menuOpen=false;const tabs=['Home','Journal','Entities','Bestiary','Templates','Layouts','Nexus','Systems','Universes','Atmosphere','Themes','Projects','Data','Media'];
function persist(){const status=document.querySelector('#status');status?.replaceChildren('Saving…');savePersistent(state).then(()=>status?.replaceChildren('Saved on this device')).catch(e=>{status?.replaceChildren('Save failed — export backup');console.error('Atlas save failed',e);alert('Could not save to IndexedDB. Export a JSON backup now. '+e.message)})}
function theme(){applyAtmosphere(state,tab==='Universes'?activeSpace:'root')}
const input=(label,key,val,extra='')=>`<label>${esc(label)}</label><input data-field="${esc(key)}" value="${esc(val)}" ${extra}>`;
const area=(label,key,val)=>`<label>${esc(label)}</label><textarea data-field="${esc(key)}">${esc(val)}</textarea>`;
const select=(label,key,value,values)=>`<label>${esc(label)}</label><select data-field="${esc(key)}">${values.map(v=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`;
const spaceField=(value)=>select('Pocket universe','spaceId',value,state.spaces.map(s=>s.id)).replace(/>([^<>]*)<\/option>/g,(all,id)=>'>'+esc(state.spaces.find(s=>s.id===id)?.name||id)+'</option>');
const list=(items,kind)=>`<div class="card"><div class="row"><input id="filter" placeholder="Search ${kind.toLowerCase()}…" value="${esc(filter)}"><button class="primary" data-add="${kind}">+ New</button></div>${items.filter(x=>JSON.stringify([x.name,x.title,x.tags]).toLowerCase().includes(filter.toLowerCase())).map(x=>`<button class="item ${selected===x.id?'active':''}" data-select="${x.id}">${esc(x.name||x.title||'Untitled')}</button>`).join('')||'<p class="hint">No entries yet.</p>'}</div>`;
// Universal internal links: [[Name]], [[entity:UUID|Label]], [[journal:UUID|Label]], [[system:UUID|Label]], [[universe:UUID|Label]].
const linkCollections={entity:'entities',journal:'journal',system:'systems',universe:'spaces'};
let navigationHistory=[];
function resolveLink(token){const explicit=token.match(/^(entity|journal|system|universe):([^|]+)(?:\|(.+))?$/i);if(explicit){const kind=explicit[1].toLowerCase(),record=state[linkCollections[kind]]?.find(x=>x.id===explicit[2]);return record?{kind,record,label:explicit[3]||record.name||record.title||'Untitled'}:null}const matches=Object.entries(linkCollections).flatMap(([kind,col])=>(state[col]||[]).filter(x=>(x.name||x.title||'').toLowerCase()===token.trim().toLowerCase()).map(record=>({kind,record,label:record.name||record.title})));return matches[0]||null}
function linkMarkup(value){return esc(String(value||'')).replace(/\[\[([^\]\n]+)\]\]/g,(_,encoded)=>{const raw=encoded.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'");const hit=resolveLink(raw);return hit?`<button type="button" class="atlas-internal-link" data-internal-kind="${hit.kind}" data-internal-id="${esc(hit.record.id)}">↗ ${esc(hit.label)}</button>`:`<span class="atlas-broken-link" title="Create or rename the target to resolve this link">[[${encoded}]]</span>`}).replace(/\[([^\]\n]+)\]\((https:\/\/[^\s)]+)\)/g,(_,label,url)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).replace(/\n/g,'<br>')}
// Embedded references use stable IDs and are rendered from current project records.
function embedCard(kind,id){const record=state[linkCollections[kind]]?.find(x=>x.id===id);if(!record)return `<div class="atlas-embed atlas-embed-missing">Missing ${esc(kind)} reference</div>`;const name=record.name||record.title||'Untitled';const excerpt=String(record.description||record.body||record.subtitle||'').replace(/\[\[[^\]]+\]\]/g,'').slice(0,210);const tags=kind==='entity'?[record.kind,...(Array.isArray(record.tags)?record.tags:[])].filter(Boolean).slice(0,4):[kind];const color=kind==='entity'&&record.appearance?.own&&/^#[0-9a-f]{6}$/i.test(record.appearance.accent||'')?record.appearance.accent:null;return `<article class="atlas-embed" ${color?`style="--embed-accent:${color}"`:''}><div class="atlas-embed-top"><span class="atlas-embed-symbol" aria-hidden="true">${({entity:'◇',journal:'✎',system:'◎',universe:'◈'})[kind]}</span><span class="atlas-embed-kind">${esc(kind)}</span></div><h4>${esc(name)}</h4>${excerpt?`<p>${esc(excerpt)}</p>`:''}<div class="atlas-embed-footer"><span>${tags.map(t=>`<span class="atlas-embed-tag">${esc(t)}</span>`).join('')}</span><button type="button" data-internal-kind="${kind}" data-internal-id="${esc(id)}" aria-label="Open ${esc(name)}">Open entry ↗</button></div></article>`}
function richReferenceMarkup(value){const raw=String(value||'');const pattern=/\{\{card:(entity|journal|system|universe):([^}\s]+)\}\}/g;let html='',cursor=0,match;while((match=pattern.exec(raw))){html+=linkMarkup(raw.slice(cursor,match.index));html+=embedCard(match[1],match[2]);cursor=pattern.lastIndex}return html+linkMarkup(raw.slice(cursor))}
function linkPreview(value){return `<div class="atlas-link-preview"><h3>Linked reading view</h3><div class="atlas-prose">${richReferenceMarkup(value)||'<p class="hint">Write [[The Hollow Archive]] or insert a permanent link below.</p>'}</div></div>`}
function linkPicker(){return `<div class="atlas-link-picker"><label>Insert a permanent Atlas hyperlink or embedded card</label><div class="row"><select id="linkTarget"><option value="">Choose an entry…</option>${Object.entries(linkCollections).flatMap(([kind,col])=>(state[col]||[]).map(x=>`<option value="${esc(kind+':'+x.id)}">${esc(kind)} · ${esc(x.name||x.title||'Untitled')}</option>`)).join('')}</select><button type="button" id="insertAtlasLink">Insert link</button><button type="button" id="insertAtlasCard">Embed card</button></div><p class="hint">Links and embedded cards survive renaming. Place the cursor in the description or journal editor before inserting.</p></div>`}
function backlinkPanel(kind,id){const refs=[];for(const [sourceKind,col,field] of [['entity','entities','description'],['journal','journal','body'],['system','systems','description']])for(const item of state[col]||[]){if(sourceKind===kind&&item.id===id)continue;const content=String(item[field]||'');const linked=[...content.matchAll(/\[\[([^\]\n]+)\]\]/g)].some(m=>{const target=resolveLink(m[1]);return target?.kind===kind&&target.record.id===id});if(linked)refs.push({kind:sourceKind,item})}return `<section class="card"><h3>Referenced by (${refs.length})</h3>${refs.map(({kind,item})=>`<button type="button" class="dashboard-link" data-internal-kind="${kind}" data-internal-id="${esc(item.id)}">${esc(item.name||item.title||'Untitled')} · ${kind}</button>`).join('')||'<p class="hint">No backlinks yet.</p>'}</section>`}
function openInternal(kind,id){const target=state[linkCollections[kind]]?.find(x=>x.id===id);if(!target)return;navigationHistory.push({tab,selected,activeSpace});if(kind==='entity'){tab='Entities';selected=id}else if(kind==='journal'){tab='Journal';selected=id}else if(kind==='system'){tab='Systems';selected=id}else{tab='Universes';activeSpace=id;selected=null}render();document.querySelector('main')?.scrollTo(0,0)}
function insertReference(editor,kind,id,card=false){const record=state[linkCollections[kind]]?.find(x=>x.id===id);if(!record||!editor)return;const value=card?`{{card:${kind}:${id}}}`:`[[${kind}:${id}|${record.name||record.title||'Untitled'}]]`;const start=editor.selectionStart??editor.value.length,end=editor.selectionEnd??start;editor.value=editor.value.slice(0,start)+value+editor.value.slice(end);editor.dispatchEvent(new Event('input',{bubbles:true}));editor.focus();editor.setSelectionRange(start+value.length,start+value.length);refreshLinkPreview()}
function bindInternalLinks(){document.querySelectorAll(':not(.atlas-link-preview) > [data-internal-kind][data-internal-id]').forEach(b=>{if(!b.closest('.atlas-link-preview'))b.addEventListener('click',()=>openInternal(b.dataset.internalKind,b.dataset.internalId))});document.querySelector('#atlasBack')?.addEventListener('click',()=>{const prior=navigationHistory.pop();if(prior){({tab,selected,activeSpace}=prior);render()}});const editor=document.querySelector('[data-field="body"]')||document.querySelector('[data-field="description"]');document.querySelector('#insertAtlasCard')?.addEventListener('click',()=>{const choice=document.querySelector('#linkTarget')?.value;if(!choice||!editor)return;const [kind,id]=choice.split(':');insertReference(editor,kind,id,true)});document.querySelector('#insertAtlasLink')?.addEventListener('click',()=>{const choice=document.querySelector('#linkTarget')?.value;if(!choice||!editor)return;const [kind,id]=choice.split(':');const record=state[linkCollections[kind]]?.find(x=>x.id===id);if(!record)return;const value=`[[${kind}:${id}|${record.name||record.title||'Untitled'}]]`;const start=editor.selectionStart??editor.value.length,end=editor.selectionEnd??start;editor.value=editor.value.slice(0,start)+value+editor.value.slice(end);editor.dispatchEvent(new Event('input',{bubbles:true}));editor.focus();editor.setSelectionRange(start+value.length,start+value.length);refreshLinkPreview()})}
// Delegation keeps freshly updated preview cards navigable without rebinding.
document.addEventListener('click',event=>{const button=event.target.closest('.atlas-link-preview [data-internal-kind][data-internal-id]');if(button)openInternal(button.dataset.internalKind,button.dataset.internalId)});
function refreshLinkPreview(){const preview=document.querySelector('.atlas-link-preview .atlas-prose');const editor=document.querySelector('[data-field="body"]')||document.querySelector('[data-field="description"]');if(preview&&editor)preview.innerHTML=richReferenceMarkup(editor.value)}
function home(){const d=state.dashboard||(state.dashboard={subtitle:'',cover:'',pinned:[],activity:[]});const project=projectList.find(p=>p.id===currentProjectId());const cover=/^https:\/\//i.test(d.cover||'')?d.cover:'';const pins=(d.pinned||[]).map(id=>state.entities.find(e=>e.id===id)).filter(Boolean);const counts=[['Entities',state.entities.length],['Journal',state.journal.length],['Links',state.links.length],['Systems',state.systems.length],['Universes',state.spaces.length]];return `<section class="world-hero" ${cover?`style="background-image:linear-gradient(90deg,#101320ee,#10132088),url('${esc(cover).replace(/'/g,'%27')}')"`:''}><span class="world-kicker">ATLAS / WORLD DASHBOARD</span><h1>${esc(project?.name||'My World')}</h1><p>${esc(d.subtitle||'Your fictional universe, at a glance.')}</p><div class="row"><button id="editDashboard" class="primary">Customize dashboard</button><button data-go="Journal">Open journal</button></div></section><div class="world-stats">${counts.map(([label,n])=>`<button class="world-stat" data-go="${label==='Links'?'Nexus':label==='Universes'?'Universes':label}"><strong>${n}</strong><span>${label}</span></button>`).join('')}</div><div class="grid"><section class="card"><div class="row"><h2 class="grow">Pinned entities</h2><button id="editPins">Edit pins</button></div>${pins.length?pins.map(e=>`<button class="dashboard-link" data-pin-open="${esc(e.id)}"><strong>${esc(e.name)}</strong><small>${esc(e.kind)}</small></button>`).join(''):'<p class="hint">Pin your most important characters, places, and artifacts here.</p>'}</section><section class="card"><h2>Recent writing</h2>${state.journal.slice(-5).reverse().map(j=>`<button class="dashboard-link" data-journal-open="${esc(j.id)}"><strong>${esc(j.title||'Untitled')}</strong><small>${esc(j.folder||'Journal')}</small></button>`).join('')||'<p class="hint">Your latest journal entries will appear here.</p>'}<button data-go="Journal">All journal entries</button></section><section class="card"><h2>Narrative systems</h2>${state.systems.slice(-5).reverse().map(sys=>`<button class="dashboard-link" data-system-open="${esc(sys.id)}"><strong>${esc(sys.name||'Unnamed system')}</strong><small>${esc(sys.type||'System')}</small></button>`).join('')||'<p class="hint">Create a causal loop, paradox, or fractal system.</p>'}<button data-go="Systems">Open System Builder</button></section><section class="card"><h2>World activity</h2><p class="hint">Recent changes made through this dashboard.</p>${(d.activity||[]).slice(-6).reverse().map(a=>`<p class="activity-line">${esc(a.message)} <small>${esc(a.when)}</small></p>`).join('')||'<p class="hint">No dashboard activity yet.</p>'}</section></div><div id="dashboardEditor" class="card" hidden><h2>Customize world dashboard</h2><label for="dashSubtitle">World description</label><textarea id="dashSubtitle" rows="2">${esc(d.subtitle||'')}</textarea><label for="dashCover">Cover image URL (HTTPS)</label><input id="dashCover" type="url" placeholder="https://example.com/cover.jpg" value="${esc(d.cover||'')}"><p class="hint">Use an HTTPS image URL. Remote images require connectivity and may not be available offline.</p><button id="saveDashboard" class="primary">Save appearance</button></div><div id="pinEditor" class="card" hidden><h2>Choose pinned entities</h2>${state.entities.map(e=>`<label class="pin-option"><input type="checkbox" data-pin-id="${esc(e.id)}" ${(d.pinned||[]).includes(e.id)?'checked':''}> ${esc(e.name)} (${esc(e.kind)})</label>`).join('')||'<p>Create entities first.</p>'}<button id="savePins" class="primary">Save pins</button></div>`}
function bindDashboard(){if(tab!=='Home')return;const d=state.dashboard;document.querySelector('#editDashboard')?.addEventListener('click',()=>{document.querySelector('#dashboardEditor').hidden=false;document.querySelector('#dashboardEditor').scrollIntoView({behavior:'smooth',block:'nearest'})});document.querySelector('#editPins')?.addEventListener('click',()=>{document.querySelector('#pinEditor').hidden=false;document.querySelector('#pinEditor').scrollIntoView({behavior:'smooth',block:'nearest'})});const log=message=>{d.activity.push({message,when:new Date().toLocaleString()});d.activity=d.activity.slice(-30)};document.querySelector('#saveDashboard')?.addEventListener('click',()=>{const url=document.querySelector('#dashCover').value.trim();if(url&&!/^https:\/\//i.test(url))return alert('Use an HTTPS image URL');d.subtitle=document.querySelector('#dashSubtitle').value;d.cover=url;log('Updated dashboard appearance');persist();render()});document.querySelector('#savePins')?.addEventListener('click',()=>{d.pinned=[...document.querySelectorAll('[data-pin-id]:checked')].map(x=>x.dataset.pinId);log('Updated pinned entities');persist();render()});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{tab=b.dataset.go;selected=null;render()});document.querySelectorAll('[data-pin-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.pinOpen;tab='Entities';render()});document.querySelectorAll('[data-journal-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.journalOpen;tab='Journal';render()});document.querySelectorAll('[data-system-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.systemOpen;tab='Systems';render()})}

function journal(){let j=state.journal.find(x=>x.id===selected)||state.journal[0];if(j)selected=j.id;return `<h1>Journal</h1><div class="split">${list(state.journal,'Journal')}<div class="card">${j?`<div class="row"><h2 class="grow">${esc(j.title)}</h2><button class="danger" data-delete="journal">Delete</button></div>${input('Title','title',j.title)}${input('Folder','folder',j.folder)}${spaceField(j.spaceId)}${area('Notes — reference entities using [[Entity Name]]','body',j.body)}${linkPicker()}${linkPreview(j.body)}${backlinkPanel("journal",j.id)}<div id="references"></div><label>Images</label><button type="button" class="media-open" data-media-for="journal">＋ Add from Photos, Camera or Files</button><div class="media-attached" id="journalMedia"></div><div class="row">${j.images.map((im,i)=>`<div><img class="journal-image" src="${esc(im.data)}" alt="${esc(im.name)}"><button data-remove-image="${i}">Remove</button></div>`).join('')}</div>`:'<p>Create a journal entry to begin.</p>'}</div></div>`}
function entities(beast=false){let items=state.entities.filter(x=>!beast||x.kind==='Creature');let e=items.find(x=>x.id===selected)||items[0];if(e)selected=e.id;let schema=state.schemas.find(s=>s.id===e?.schemaId);return `<h1>${beast?'Bestiary':'Entity Library'}</h1><div class="split">${list(items,beast?'Creature':'Entity')}<div>${e?`<div class="card" style="${entityStyle(e)}"><div class="row"><h2 class="grow">${esc(e.name)}</h2><button class="danger" data-delete="entity">Delete</button></div>${input('Name','name',e.name)}${select('Category','kind',e.kind,['Character','Item','Place','Creature','Faction','Event','Concept','Other'])}${spaceField(e.spaceId)}${area('Description / lore','description',e.description||'')}${linkPicker()}${linkPreview(e.description||'')}<button type="button" class="media-open" data-media-for="entity">＋ Add portrait or gallery image</button><div class="media-attached" id="entityMedia"></div>${backlinkPanel('entity',e.id)}${input('Tags (comma separated)','tags',Array.isArray(e.tags)?e.tags.join(', '):e.tags||'')}${select('Bestiary template','schemaId',e.schemaId||'', ['',...state.schemas.map(s=>s.id)])}<h3>Custom traits</h3>${(schema?.fields||[]).map(f=>{let type=schema.fieldTypes[f]||'text',v=e.traits[f]??'';return type==='longtext'?`<label>${esc(f)}</label><textarea data-trait="${esc(f)}">${esc(v)}</textarea>`:type==='boolean'?`<label>${esc(f)}</label><select data-trait="${esc(f)}"><option value="">Unknown</option><option ${v==='Yes'?'selected':''}>Yes</option><option ${v==='No'?'selected':''}>No</option></select>`:`<label>${esc(f)}</label><input data-trait="${esc(f)}" type="${type==='number'?'number':'text'}" value="${esc(v)}">`}).join('')}<div class="row"><input id="traitName" placeholder="Additional trait name"><button id="addTrait">Add</button></div>${Object.entries(e.traits).filter(([k])=>!schema?.fields.includes(k)).map(([k,v])=>`<label>${esc(k)}</label><input data-trait="${esc(k)}" value="${esc(v)}">`).join('')}</div><div class="card"><h2>Appearance</h2><label>Background image URL (optional)</label><input id="entityBackground" placeholder="https://example.com/background.jpg" value="${esc(e.appearance?.backgroundImage||'')}"><label><input type="checkbox" id="ownTheme" ${e.appearance?.own?'checked':''} style="width:auto"> Override inherited theme</label>${['bg','panel','card','ink','accent'].map(k=>`<label>${k}</label><input type="color" data-appearance="${k}" value="${esc(e.appearance?.[k]||state.theme[k])}" ${e.appearance?.own?'':'disabled'}>`).join('')}${select('Font override','appearanceFont',e.appearance?.font||state.theme.font,['system-ui','Georgia','monospace','Arial','serif'])}</div>`:'<div class="card">Create your first entity.</div>'}${e?entityLayoutControls(e):''}${masterFields(e)}${layoutForEntity(e)}${beast?schemaEditor():''}</div></div>`}

function entityLayoutControls(e){return `<div class="card"><h2>Entity page layout</h2><label>Layout source</label><select id="layoutMode"><option value="inherit" ${e.layoutMode!=='custom'?'selected':''}>Inherit reusable layout</option><option value="custom" ${e.layoutMode==='custom'?'selected':''}>Custom layout for this entity</option></select><label>Reusable layout</label><select id="entityLayout"><option value="">Default layout</option>${state.layouts.map(l=>`<option value="${esc(l.id)}" ${e.layoutId===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select><div class="row"><button id="editEntityLayout">Edit this entity's layout</button><button id="saveEntityLayout">Save as reusable</button></div><h3>Live page preview</h3>${preview(e,state)}</div>`}
function layoutEditor(){if(!layoutSelection||!state.layouts.some(x=>x.id===layoutSelection))layoutSelection=state.layouts[0]?.id||null;let e=state.entities.find(x=>x.id===selected);let preset=state.layouts.find(x=>x.id===layoutSelection);let panels=layoutTarget==='entity'?e?.layout:preset?.panels;return `<h1>Visual Layout Builder</h1><p class="hint">Arrange panels, rename headings, and save reusable layouts. Entity-specific layouts override inherited layouts without changing other pages.</p><div class="card"><div class="row"><input id="newLayoutName" placeholder="New layout name"><button id="createLayout" class="primary">Create reusable layout</button></div><label>Editing</label><select id="layoutTarget"><option value="preset" ${layoutTarget==='preset'?'selected':''}>Reusable layout</option><option value="entity" ${layoutTarget==='entity'?'selected':''}>Individual entity</option></select>${layoutTarget==='preset'?`<label>Choose layout</label><select id="layoutSelection">${state.layouts.map(l=>`<option value="${esc(l.id)}" ${l.id===layoutSelection?'selected':''}>${esc(l.name)}</option>`).join('')}</select>`:`<label>Choose entity</label><select id="layoutEntity">${state.entities.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`}</div>${panels?`<div class="split"><div class="card"><h2>Panel arrangement</h2><p class="hint">Drag panel handles to reorder, or use arrows. Choose half/full width and edit panel content.</p>${panels.map((p,i)=>`<div class="layout-edit-panel" draggable="true" data-sort-panel="${i}"><div class="row"><span class="drag-handle" aria-hidden="true">⠿</span><strong class="grow">${i+1}. ${esc(p.type)}</strong><button data-panel-up="${i}" ${i===0?'disabled':''}>↑</button><button data-panel-down="${i}" ${i===panels.length-1?'disabled':''}>↓</button><button class="danger" data-panel-delete="${i}">×</button></div><label>Heading</label><input data-panel-title="${i}" value="${esc(p.title||'')}"><label>Panel type</label><select data-panel-type="${i}">${panelTypes.map(t=>`<option ${p.type===t?'selected':''}>${t}</option>`).join('')}</select><label>Width</label><select data-panel-width="${i}"><option value="half" ${p.width!=='wide'?'selected':''}>Half</option><option value="wide" ${p.width==='wide'?'selected':''}>Full</option></select>${['notes','image','heading'].includes(p.type)?`<label>${p.type==='image'?'Image URL': 'Panel content'}</label><textarea data-panel-content="${i}">${esc(p.content||'')}</textarea>`:''}</div>`).join('')}<div class="row"><select id="newPanelType">${panelTypes.map(t=>`<option>${t}</option>`).join('')}</select><button id="addPanel" class="primary">Add panel</button></div>${layoutTarget==='preset'?`<button class="danger" id="deleteLayout">Delete reusable layout</button>`:''}</div><div class="card"><h2>Live preview</h2>${preview(layoutTarget==='entity'?e:{...(state.entities[0]||{id:'sample',name:'Sample character',kind:'Character',traits:{},appearance:{}}),layoutMode:'custom',layout:panels},state)}</div></div>`:'<div class="card">Create a reusable layout or select an entity to begin.</div>'}`}
function templates(){return `<h1>Master Entity Templates</h1><p class="hint">Create reusable groups of traits and tabs. Entities inherit template defaults until you override a field.</p><div class="card"><div class="row"><input id="masterName" placeholder="Template name, e.g. NPC"><button id="addMaster" class="primary">Create template</button></div></div>${state.masters.map(m=>`<div class="card"><div class="row"><h2 class="grow">${esc(m.name)}</h2><button data-remove-master="${esc(m.id)}" class="danger">Delete</button></div>${input('Template name','masterName:'+m.id,m.name)}<h3>Reusable tabs</h3>${m.tabs.map((t,i)=>`<div class="row"><input data-master-tab="${esc(m.id)}" data-index="${i}" value="${esc(t)}"><button data-drop-tab="${esc(m.id)}" data-index="${i}">×</button></div>`).join('')}<div class="row"><input data-tab-name="${esc(m.id)}" placeholder="New tab name"><button data-add-tab="${esc(m.id)}">Add tab</button></div><h3>Default traits</h3>${Object.entries(m.traits).map(([k,v])=>`<div class="row"><span>${esc(k)}</span><input data-master-trait="${esc(m.id)}" data-trait-key="${esc(k)}" value="${esc(v)}"><button data-drop-master-trait="${esc(m.id)}" data-trait-key="${esc(k)}">×</button></div>`).join('')}<div class="row"><input data-master-key="${esc(m.id)}" placeholder="New trait label"><button data-add-master-trait="${esc(m.id)}">Add trait</button></div></div>`).join('')||'<div class="card">Create your first master template.</div>'}`}
function masterFields(e){if(!e)return '';let m=state.masters.find(x=>x.id===e.masterId);return `<div class="card"><h2>Master template & custom tabs</h2><label>Inherit from</label><select id="entityMaster"><option value="">None</option>${state.masters.map(x=>`<option value="${esc(x.id)}" ${e.masterId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${m?`<p class="hint">Inherited fields can be overridden individually. Clear an override to restore the default.</p>${m.tabs.map(t=>`<div class="card"><h3>${esc(t)}</h3>${Object.entries(m.traits).filter(([k])=>k.startsWith(t+' / ')).map(([k,v])=>`<label>${esc(k.slice(t.length+3))} ${Object.hasOwn(e.traits,k)?'(overridden)':'(inherited)'}</label><div class="row"><input data-inherited="${esc(k)}" value="${esc(e.traits[k]??v)}"><button data-clear-inherited="${esc(k)}">Reset</button></div>`).join('')||'<p class="hint">No fields in this tab yet. Add traits prefixed with “'+esc(t)+' / ” in Templates.</p>'}</div>`).join('')}`:''}</div>`}

const defaultPanels=()=>[{id:uid(),type:'overview',title:'Overview',width:'wide'},{id:uid(),type:'traits',title:'Traits',width:'half'},{id:uid(),type:'links',title:'Connections',width:'half'}];
function effectiveLayout(e){return state.layouts.find(l=>l.id===e?.layoutId)}
function layoutForEntity(e){if(!e)return '';let l=effectiveLayout(e);return `<div class="card"><h2>Page layout</h2><p class="hint">Use a reusable layout, or detach a copy to customize this entity alone.</p><label>Layout</label><select id="entityLayout"><option value="">Standard page</option>${state.layouts.map(x=>`<option value="${esc(x.id)}" ${e.layoutId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><div class="row"><button id="editEntityLayout">${l?'Edit layout':'Create layout'}</button>${l?'<button id="detachLayout">Duplicate for this entity</button>':''}</div>${l?`<div class="layout-preview" style="${layoutStyle(l)}">${l.panels.map(p=>panelPreview(p,e)).join('')}</div>`:''}</div>`}
function layoutStyle(l){let a=l.appearance||{};return `--layout-accent:${esc(a.accent||state.theme.accent)};--layout-font:${esc(a.font||state.theme.font)};--layout-surface:${esc(a.surface||state.theme.card)}`}
function panelPreview(p,e){let text=p.type==='overview'?e?.description||'Entity description':p.type==='traits'?Object.entries(e?.traits||{}).map(([k,v])=>`${k}: ${v}`).join(' · ')||'Custom traits':p.type==='links'?state.links.filter(x=>x.from===e?.id||x.to===e?.id).length+' narrative connections':p.type==='notes'?p.content||'Notes':p.type==='image'?'Image panel (URL configured in editor)':p.type==='heading'?p.content||p.title:'';return `<div class="layout-panel ${p.width==='wide'?'wide':''}">${p.type==='divider'?'<hr>':`<strong>${esc(p.title)}</strong>${p.type==='image'&&p.content?`<img class="panel-img" src="${esc(p.content)}" alt="${esc(p.title)}">`:`<p>${esc(text)}</p>`}`}</div>`}
function layouts(){let l=state.layouts.find(x=>x.id===selected)||state.layouts[0];if(l)selected=l.id;return `<h1>Visual Layout Builder</h1><p class="hint">Build reusable page layouts. Reorder panels, choose content, set widths and theme accents. Changes to a shared layout update every entity using it.</p><div class="split">${list(state.layouts,'Layout')}<div>${l?`<div class="card"><div class="row"><h2 class="grow">Layout editor</h2><button data-remove-layout="${esc(l.id)}" class="danger">Delete</button></div><label>Name</label><input id="layoutName" value="${esc(l.name)}"><div class="row"><button id="duplicateLayout">Duplicate</button><button id="addPanel" class="primary">+ Add panel</button></div><h3>Panels</h3>${l.panels.map((p,i)=>`<div class="layout-editor-panel"><div class="row"><strong class="grow">${i+1}. ${esc(p.title)}</strong><button data-move-panel="${esc(p.id)}" data-direction="-1" ${i===0?'disabled':''}>↑</button><button data-move-panel="${esc(p.id)}" data-direction="1" ${i===l.panels.length-1?'disabled':''}>↓</button><button data-remove-panel="${esc(p.id)}" class="danger">×</button></div><label>Title</label><input data-panel-title="${esc(p.id)}" value="${esc(p.title)}"><div class="row"><div class="grow"><label>Content type</label><select data-panel-type="${esc(p.id)}">${panelTypes.map(t=>`<option ${p.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="grow"><label>Width</label><select data-panel-width="${esc(p.id)}"><option value="half" ${p.width==='half'?'selected':''}>Half</option><option value="wide" ${p.width==='wide'?'selected':''}>Full</option></select></div></div>${['notes','image','heading'].includes(p.type)?`<label>${p.type==='image'?'Image URL':'Text'}</label><textarea data-panel-content="${esc(p.id)}">${esc(p.content||'')}</textarea>`:''}</div>`).join('')}<h3>Layout appearance</h3><div class="row"><div class="grow"><label>Accent</label><input type="color" id="layoutAccent" value="${esc(l.appearance?.accent||state.theme.accent)}"></div><div class="grow"><label>Surface</label><input type="color" id="layoutSurface" value="${esc(l.appearance?.surface||state.theme.card)}"></div></div><label>Font</label><select id="layoutFont">${['system-ui','Georgia','monospace','Arial','serif'].map(f=>`<option ${f===(l.appearance?.font||state.theme.font)?'selected':''}>${f}</option>`).join('')}</select></div><div class="card"><h2>Live preview</h2><div class="layout-preview" style="${layoutStyle(l)}">${l.panels.map(p=>panelPreview(p,state.entities.find(e=>e.layoutId===l.id))).join('')}</div></div>`:'<div class="card">Create a layout to begin.</div>'}</div></div>`}
function bindLayouts(){const l=state.layouts.find(x=>x.id===selected);document.querySelector('#entityLayout')?.addEventListener('change',ev=>{let e=state.entities.find(x=>x.id===selected);e.layoutId=ev.target.value;persist();render()});document.querySelector('#editEntityLayout')?.addEventListener('click',()=>{let e=state.entities.find(x=>x.id===selected);let l=effectiveLayout(e);if(!l){l={id:uid(),name:e.name+' Layout',panels:defaultPanels(),appearance:{}};state.layouts.push(l);e.layoutId=l.id}selected=l.id;tab='Layouts';persist();render()});document.querySelector('#detachLayout')?.addEventListener('click',()=>{let e=state.entities.find(x=>x.id===selected),old=effectiveLayout(e);if(!old)return;let copy=structuredClone(old);copy.id=uid();copy.name=e.name+' Layout';copy.panels.forEach(p=>p.id=uid());state.layouts.push(copy);e.layoutId=copy.id;selected=copy.id;tab='Layouts';persist();render()});if(tab!=='Layouts')return;document.querySelector('#layoutName')?.addEventListener('input',ev=>{l.name=ev.target.value;persist()});let touchPanel=null;document.querySelectorAll('.drag-handle').forEach(handle=>{handle.setAttribute('role','button');handle.setAttribute('aria-label','Hold and drag to reorder panel');handle.style.touchAction='none';handle.addEventListener('pointerdown',ev=>{if(ev.pointerType==='mouse')return;const el=handle.closest('[data-sort-panel]');touchPanel={from:Number(el.dataset.sortPanel),id:ev.pointerId};handle.setPointerCapture(ev.pointerId)});handle.addEventListener('pointerup',ev=>{if(!touchPanel||touchPanel.id!==ev.pointerId)return;const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-sort-panel]');if(target){const to=Number(target.dataset.sortPanel),from=touchPanel.from;if(from!==to)updatePanels(p=>{const [moved]=p.splice(from,1);p.splice(to,0,moved)})}touchPanel=null});handle.addEventListener('pointercancel',()=>touchPanel=null)});let draggedPanel=null;document.querySelectorAll('[data-sort-panel]').forEach(el=>{el.addEventListener('dragstart',ev=>{draggedPanel=Number(el.dataset.sortPanel);ev.dataTransfer.effectAllowed='move'});el.addEventListener('dragover',ev=>ev.preventDefault());el.addEventListener('drop',ev=>{ev.preventDefault();let target=Number(el.dataset.sortPanel);if(draggedPanel===null||draggedPanel===target)return;updatePanels(p=>{const [moved]=p.splice(draggedPanel,1);p.splice(target,0,moved)});draggedPanel=null})});
document.querySelector('#addPanel')?.addEventListener('click',()=>{l.panels.push({id:uid(),type:'notes',title:'New panel',width:'half',content:''});persist();render()});document.querySelector('#duplicateLayout')?.addEventListener('click',()=>{let copy=structuredClone(l);copy.id=uid();copy.name=l.name+' Copy';copy.panels.forEach(p=>p.id=uid());state.layouts.push(copy);selected=copy.id;persist();render()});document.querySelectorAll('[data-remove-layout]').forEach(b=>b.onclick=()=>{if(!confirm('Delete layout? Entities will return to standard pages.'))return;state.layouts=state.layouts.filter(x=>x.id!==b.dataset.removeLayout);state.entities.forEach(e=>{if(e.layoutId===b.dataset.removeLayout)e.layoutId=''});selected=null;persist();render()});document.querySelectorAll('[data-move-panel]').forEach(b=>b.onclick=()=>{let i=l.panels.findIndex(p=>p.id===b.dataset.movePanel),j=i+Number(b.dataset.direction);if(j<0||j>=l.panels.length)return;[l.panels[i],l.panels[j]]=[l.panels[j],l.panels[i]];persist();render()});document.querySelectorAll('[data-remove-panel]').forEach(b=>b.onclick=()=>{l.panels=l.panels.filter(p=>p.id!==b.dataset.removePanel);persist();render()});for(let [attr,key] of [['title','title'],['type','type'],['width','width'],['content','content']])document.querySelectorAll('[data-panel-'+attr+']').forEach(el=>el.addEventListener(attr==='type'||attr==='width'?'change':'input',()=>{let p=l.panels.find(x=>x.id===el.dataset['panel'+attr[0].toUpperCase()+attr.slice(1)]);if(!p)return;p[key]=el.value;persist();if(attr==='type'||attr==='width')render()}));for(let [id,key] of [['layoutAccent','accent'],['layoutSurface','surface'],['layoutFont','font']])document.getElementById(id)?.addEventListener('change',ev=>{l.appearance??={};l.appearance[key]=ev.target.value;persist();render()})}
function entityStyle(e){if(!e.appearance?.own)return '';return `background:${esc(e.appearance.bg||state.theme.bg)};${/^https?:\/\//.test(e.appearance.backgroundImage||'')?`background-image:linear-gradient(#0008,#0008),url(&quot;${esc(e.appearance.backgroundImage)}&quot;);background-size:cover;`:''}color:${esc(e.appearance.ink||state.theme.ink)};font-family:${esc(e.appearance.font||state.theme.font)};border-color:${esc(e.appearance.accent||state.theme.accent)}`}
function schemaEditor(){return `<div class="card"><h2>Bestiary templates</h2><div class="row"><input id="schemaName" placeholder="Template name"><button id="newSchema">Create</button></div>${state.schemas.map(s=>`<div class="card"><h3>${esc(s.name)}</h3>${s.fields.map(f=>`<div class="row"><span class="grow">${esc(f)}</span><select data-type="${esc(s.id)}" data-name="${esc(f)}" style="max-width:130px">${['text','longtext','number','boolean'].map(t=>`<option ${s.fieldTypes[f]===t?'selected':''}>${t}</option>`).join('')}</select><button data-remove-field="${esc(s.id)}" data-name="${esc(f)}">×</button></div>`).join('')}<div class="row"><input data-new-field="${esc(s.id)}" placeholder="New trait label"><button data-add-field="${esc(s.id)}">Add trait</button></div></div>`).join('')}</div>`}
function nexus(){let cs=cycles(state.entities,state.links);return `<h1>Narrative Nexus</h1><p class="hint">Drag nodes to arrange. Causal cycles are detected structurally, not proven paradoxes.</p><div class="card"><div class="row"><select id="linkFrom">${state.entities.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select><select id="linkKind">${['relates','causal','loop','paradox','fractal','contains','opposes'].map(k=>`<option>${k}</option>`).join('')}</select><select id="linkTo">${state.entities.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select><button id="addLink" class="primary">Connect</button></div></div><div class="nexus-tools" role="toolbar" aria-label="Nexus zoom"><button id="zoomOut" aria-label="Zoom out">−</button><output id="zoomLevel">100%</output><button id="zoomIn" aria-label="Zoom in">+</button><button id="zoomReset">Reset view</button><span class="hint">Pinch to zoom · drag empty space to pan</span></div><div class="canvas" id="canvas"><div class="nexus-world" id="nexusWorld"><svg class="edges" id="edges"></svg>${state.entities.map((e,i)=>`<div class="node" data-node="${e.id}" style="left:${e.x??(35+i%4*155)}px;top:${e.y??(35+Math.floor(i/4)*105)}px"><b>${esc(e.name)}</b><small>${esc(e.kind)}</small></div>`).join('')}</div></div><div class="grid"><div class="card"><h2>Relationships</h2>${state.links.map(l=>`<div class="row"><span class="grow">${esc(state.entities.find(e=>e.id===l.from)?.name||'?')} → ${esc(l.kind)} → ${esc(state.entities.find(e=>e.id===l.to)?.name||'?')}</span><button data-unlink="${l.id}">×</button></div>`).join('')}</div><div class="card"><h2>Detected causal cycles (${cs.length})</h2>${cs.map(c=>`<p>${c.map(id=>esc(state.entities.find(e=>e.id===id)?.name||'?')).join(' → ')}</p>`).join('')||'<p class="hint">None detected.</p>'}</div></div>`}
function systems(){let s=state.systems.find(x=>x.id===selected)||state.systems[0];if(s)selected=s.id;return `<h1>Narrative System Builder</h1><div class="split">${list(state.systems,'System')}<div class="card">${s?`<div class="row"><h2 class="grow">${esc(s.name)}</h2><button data-delete="system" class="danger">Delete</button></div>${input('Name','name',s.name)}${select('Logic lens','kind',s.kind,['Fractal','Paradox','Causal Loop','Custom'])}${spaceField(s.spaceId)}${area('Rules, contradictions and narrative notes','description',s.description||'')}${linkPicker()}${linkPreview(s.description||'')}${backlinkPanel('system',s.id)}<label>Parent system</label><select data-field="parentId"><option value="">None</option>${state.systems.filter(x=>x.id!==s.id&&!descendant(state.systems,x.id,s.id)).map(x=>`<option value="${x.id}" ${s.parentId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><h3>Ordered states</h3>${s.steps.map((step,i)=>`<div class="row"><input data-step="${i}" value="${esc(typeof step==='string'?step:step.name||step.label||JSON.stringify(step))}"><button data-remove-step="${i}">×</button></div>`).join('')}<button id="addStep">+ State</button><p class="hint">${s.kind==='Causal Loop'?'The final state is interpreted as returning to the first.':s.kind==='Paradox'?'Describe mutually incompatible rules to document the paradox.':s.kind==='Fractal'?'Use parent/child systems to describe recursive patterns.':'Define your own logic.'}</p>`:'Create a narrative system.'}</div></div>`}
function universes(){return `<h1>Pocket Universes</h1><div class="card"><div class="row"><input id="spaceName" placeholder="New universe name"><button id="addSpace" class="primary">Create</button></div></div><div class="grid">${state.spaces.map(s=>`<div class="card"><h2>${esc(s.name)}</h2>${s.id!=='root'?`<label>Name</label><input data-space-name="${s.id}" value="${esc(s.name)}"><label>Parent universe</label><select data-space-parent="${s.id}"><option value="root">Main Universe</option>${state.spaces.filter(x=>x.id!==s.id&&x.id!=='root'&&!spaceDescendant(x.id,s.id)).map(x=>`<option value="${x.id}" ${s.parent===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="danger" data-remove-space="${s.id}">Delete</button>`:'<p class="hint">Root of your atlas</p>'}<p class="hint">${state.entities.filter(e=>e.spaceId===s.id).length} entities · ${state.journal.filter(j=>j.spaceId===s.id).length} notes</p></div>`).join('')}</div>`}
function spaceDescendant(id,ancestor){let seen=new Set();while(id&&!seen.has(id)){if(id===ancestor)return true;seen.add(id);id=state.spaces.find(x=>x.id===id)?.parent}return false}
function themes(){return `<h1>Theme Studio</h1><div class="grid"><div class="card"><h2>Global appearance</h2>${['bg','panel','card','ink','accent'].map(k=>`<label>${k}</label><input type="color" data-theme="${k}" value="${esc(state.theme[k])}">`).join('')}${select('Font','font',state.theme.font,['system-ui','Georgia','monospace','Arial','serif'])}<div class="preview">Atlas preview · Worlds within worlds</div><div class="row"><input id="presetName" placeholder="Preset name"><button id="savePreset">Save preset</button></div></div><div class="card"><h2>Reusable presets</h2>${state.presets.map(p=>`<div class="card"><b>${esc(p.name)}</b><div class="row"><button data-preset="${p.id}">Apply</button><button class="danger" data-delete-preset="${p.id}">Delete</button></div></div>`).join('')||'<p class="hint">No presets yet.</p>'}<p class="hint">Entity overrides are edited on each entity page. Unmodified entities inherit the global theme.</p></div></div>`}
function atmosphere(){const a=state.atmosphere;return `<h1>Atmosphere Engine</h1><p class="hint">Choose a presentation skin without changing your world data. Each pocket universe can override the global atmosphere.</p><div class="atmos-grid">${Object.entries(atmospheres).map(([key,t])=>`<button class="atmos-card ${a.preset===key?'chosen':''}" data-atmos="${key}" style="--sw-bg:${t.bg};--sw-panel:${t.panel};--sw-accent:${t.accent};--sw-ink:${t.ink};font-family:${t.font}"><span class="swatch"><span class="swatch-title">${t.name}</span><span class="swatch-panel">ENTITY FILE · 001<br>Worlds within worlds<br>✧ ─── ◈ ─── ✧</span></span><strong>${t.name}</strong></button>`).join('')}</div><div class="card"><h2>Accessibility & effects</h2><label><input type="checkbox" id="atmosEffects" ${a.effects?'checked':''} style="width:auto"> Enable atmospheric overlays</label><label><input type="checkbox" id="atmosMotion" ${a.motion?'checked':''} style="width:auto"> Enable subtle animation</label><label><input type="checkbox" id="atmosCustom" ${a.useCustom?'checked':''} style="width:auto"> Use my custom Theme Studio palette instead</label><p class="hint">Motion is also disabled automatically when your device requests reduced motion. Effects never change saved entity content.</p></div><div class="card"><h2>Pocket-universe atmosphere</h2>${state.spaces.map(sp=>`<label>${esc(sp.name)}</label><select data-space-atmos="${esc(sp.id)}"><option value="">Inherit global theme</option>${Object.entries(atmospheres).map(([key,t])=>`<option value="${key}" ${sp.atmosphere===key?'selected':''}>${t.name}</option>`).join('')}</select>`).join('')}</div>`}
function explorer(){const children=spaceTree(state);function branch(id,depth=0,seen=new Set()){if(depth>12||seen.has(id))return '';const next=new Set(seen);next.add(id);return (children.get(id)||[]).map(sp=>`<div class="universe-branch" style="margin-left:${Math.min(depth,5)*18}px"><button class="universe-orb" data-enter-space="${esc(sp.id)}"><span class="orb-icon">✦</span><span><strong>${esc(sp.name)}</strong><small>${state.entities.filter(e=>e.spaceId===sp.id).length} entities · ${esc(atmospheres[atmosphereOf(state,sp.id)]?.name||'Custom')}</small></span></button>${branch(sp.id,depth+1,next)}</div>`).join('')};const current=state.spaces.find(s=>s.id===activeSpace)||state.spaces[0];return `<div class="card explorer"><div class="row"><h2 class="grow">Universe Explorer</h2><button data-enter-space="root">Main Universe</button></div><div class="universe-orb root-orb"><span class="orb-icon">◉</span><span><strong>${esc(state.spaces.find(s=>s.id==='root')?.name||'Main Universe')}</strong><small>Root reality</small></span></div>${branch('root')}<p class="hint">Select a universe to inspect its contents and atmosphere.</p><div class="card"><h3>${esc(current.name)}</h3><p>${state.entities.filter(e=>e.spaceId===current.id).map(e=>`<button class="mini-entity" data-open-entity="${esc(e.id)}">${esc(e.name)} · ${esc(e.kind)}</button>`).join('')||'No entities assigned yet.'}</p></div></div>`}
function entityCards(){return `<div class="card"><h2>Entity dossiers</h2><div class="dossier-grid">${state.entities.slice(-8).reverse().map(e=>{const a=e.appearance?.own?{...state.theme,...e.appearance}:atmospheres[atmosphereOf(state,e.spaceId)]||atmospheres.cosmic;return `<button class="dossier" data-open-entity="${esc(e.id)}" style="--dossier-bg:${esc(a.panel)};--dossier-accent:${esc(a.accent)};--dossier-ink:${esc(a.ink)};font-family:${esc(a.font||'system-ui')}"><span class="dossier-mark">✧</span><small>ENTITY · ${esc(e.kind)}</small><strong>${esc(e.name)}</strong><span>${esc((e.description||'No description yet').slice(0,110))}</span><small>${state.links.filter(l=>l.from===e.id||l.to===e.id).length} connections</small></button>`}).join('')||'<p class="hint">Create entities to see their themed dossier cards.</p>'}</div></div>`}
let projectList=[];
async function refreshProjects(){projectList=await listProjects();if(tab==='Projects')render()}
function projectsPage(){return `<h1>World Projects</h1><p class="muted">Independent worlds stored on this device. Switch without overwriting another world. Export backups for safety.</p><div class="card"><h2>Create a world</h2><div class="row"><input id="projectName" placeholder="World name" aria-label="New world name"><button class="primary" id="projectCreate">Create world</button></div><p class="hint">Create a blank world, or duplicate the current world with all its entities and settings.</p><button id="projectDuplicate">Duplicate current world</button></div><div class="grid">${projectList.map(p=>`<div class="card"><h2>${esc(p.name)} ${p.id===currentProjectId()?'(Active)':''}</h2><p class="hint">Updated ${esc((p.updatedAt||'').slice(0,10))}</p><div class="row"><button data-project-open="${esc(p.id)}" ${p.id===currentProjectId()?'disabled':''}>Open</button><button data-project-rename="${esc(p.id)}">Rename</button><button data-project-delete="${esc(p.id)}" class="danger" ${p.id===currentProjectId()?'disabled':''}>Delete</button></div></div>`).join('')}</div><div class="card"><h2>Backups</h2><p>Export the active world from the top toolbar. To create a world from a JSON backup, use Import as New Project below.</p><input id="projectImport" type="file" accept=".json,application/json" aria-label="Import world as new project"></div>`}
async function projectAction(fn){try{await fn();projectList=await listProjects();render()}catch(e){console.error(e);alert('Project operation failed: '+e.message)}}
function bindProjects(){if(tab!=='Projects')return;document.querySelector('#projectCreate')?.addEventListener('click',()=>projectAction(async()=>{const name=document.querySelector('#projectName').value.trim();if(!name)return alert('Enter a world name');const id=await createProject(name);state=await switchProject(id);selected=null;activeSpace='root'}));document.querySelector('#projectDuplicate')?.addEventListener('click',()=>projectAction(async()=>{const name=prompt('Name the duplicate','Copy of '+(projectList.find(p=>p.id===currentProjectId())?.name||'World'));if(!name?.trim())return;await flushSaves();const id=await createProject(name.trim(),state);state=await switchProject(id);selected=null;activeSpace='root'}));document.querySelectorAll('[data-project-open]').forEach(b=>b.onclick=()=>projectAction(async()=>{state=await switchProject(b.dataset.projectOpen);selected=null;activeSpace='root';filter=''}));document.querySelectorAll('[data-project-rename]').forEach(b=>b.onclick=()=>projectAction(async()=>{const p=projectList.find(x=>x.id===b.dataset.projectRename);const name=prompt('World name',p.name);if(name?.trim())await renameProject(p.id,name.trim())}));document.querySelectorAll('[data-project-delete]').forEach(b=>b.onclick=()=>projectAction(async()=>{const p=projectList.find(x=>x.id===b.dataset.projectDelete);if(confirm('Permanently delete "'+p.name+'" from this device? This cannot be undone.'))await deleteProject(p.id)}));document.querySelector('#projectImport')?.addEventListener('change',e=>projectAction(async()=>{const file=e.target.files[0];if(!file)return;const obj=JSON.parse(await file.text());if(!Array.isArray(obj.entities)||!Array.isArray(obj.journal))throw Error('Invalid Atlas JSON');const id=await createProject(file.name.replace(/\.json$/i,''),normalize(obj));state=await switchProject(id);selected=null;activeSpace='root'}))}
function data(){return `<h1>Data & Portability</h1><div class="card"><h2>Local-first project</h2><p>Your world is saved in this browser. Other browsers and iPhones do not automatically sync.</p><div class="toolbar"><button id="export" class="primary">Export JSON backup</button><label style="margin:0">Import JSON (replaces world)<input id="import" type="file" accept=".json,application/json"></label><button class="danger" id="reset">Reset world</button></div><p class="hint">Atlas v4 can read v1–v3 browser saves and their JSON structures. Export a backup before upgrading or importing. Future apps should read the exported JSON, not this browser's local storage.</p></div>`}
function render(){theme();document.body.dataset.displayMode=displayMode;app.innerHTML=`<div class="shell"><aside class="sidebar ${menuOpen?'menu-open':''}" id="atlasSidebar"><div class="brand">ATLAS <span>STUDIO</span></div><div class="mobile-menu-heading"><strong>All sections</strong><button type="button" id="closeMenu" aria-label="Close menu">✕</button></div>${tabs.map(t=>`<button class="nav ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</aside><button class="menu-backdrop ${menuOpen?'visible':''}" id="menuBackdrop" aria-label="Close navigation"></button><main>${navigationHistory.length?`<button type="button" id="atlasBack" class="atlas-back">← Back to previous page</button>`:''}<div class="mobile-header"><button id="openMenu" aria-label="Open all sections">☰</button><strong>ATLAS <span>STUDIO</span></strong><span>${esc(tab)}</span></div><div class="top"><button id="atlasSearchOpen" type="button" class="atlas-search-open" aria-keyshortcuts="Control+K Meta+K">⌕ Search <span class="atlas-search-hint">⌘ / Ctrl K</span></button><button id="openMedia" type="button">＋ Add photo</button><span class="status" id="status">Saved locally · Atlas</span><div class="row"><label class="mode-label" for="displayMode">View</label><select id="displayMode" aria-label="Display mode"><option value="auto" ${displayMode==='auto'?'selected':''}>Auto</option><option value="mobile" ${displayMode==='mobile'?'selected':''}>Mobile</option><option value="desktop" ${displayMode==='desktop'?'selected':''}>Desktop</option></select><button id="installAtlas" type="button">Install Atlas</button><span id="networkStatus" class="hint">${navigator.onLine?'Online':'Offline ready'}</span><button id="quickExport">Export backup</button></div></div>${({Home:()=>home()+entityCards(),Journal:journal,Entities:()=>entities(),Bestiary:()=>entities(true),Templates:templates,Layouts:layoutEditor,Nexus:nexus,Systems:systems,Universes:()=>explorer()+universes(),Atmosphere:atmosphere,Themes:themes,Projects:projectsPage,Data:data,Media:mediaPage})[tab]()}</main><nav class="mobile-bottom" aria-label="Quick navigation">${["Home","Journal","Entities","Nexus"].map(t=>`<button class="mobile-tab ${tab===t?'active':''}" data-tab="${t}">${({Home:"⌂",Journal:"✎",Entities:"◇",Nexus:"◎"})[t]}<small>${t}</small></button>`).join('')}<button class="mobile-tab" id="moreMenu">☷<small>More</small></button></nav></div>`;bind();document.querySelector('#displayMode')?.addEventListener('change',e=>{displayMode=e.target.value;localStorage.setItem('atlas-display-mode',displayMode);menuOpen=false;render()});document.querySelector('#openMenu')?.addEventListener('click',()=>{menuOpen=true;render()});document.querySelector('#moreMenu')?.addEventListener('click',()=>{menuOpen=true;render()});document.querySelector('#closeMenu')?.addEventListener('click',()=>{menuOpen=false;render()});document.querySelector('#menuBackdrop')?.addEventListener('click',()=>{menuOpen=false;render()});bindLayouts();bindAtmosphere();bindProjects();bindDashboard();bindInternalLinks();bindMedia();if(tab==='Nexus')drawEdges();if(tab==='Journal')references()}
function bindAtmosphere(){document.querySelectorAll('[data-atmos]').forEach(b=>b.onclick=()=>{state.atmosphere.preset=b.dataset.atmos;state.atmosphere.useCustom=false;persist();render()});for(const [id,key] of [['atmosEffects','effects'],['atmosMotion','motion'],['atmosCustom','useCustom']])document.getElementById(id)?.addEventListener('change',e=>{state.atmosphere[key]=e.target.checked;persist();render()});document.querySelectorAll('[data-space-atmos]').forEach(el=>el.onchange=()=>{state.spaces.find(s=>s.id===el.dataset.spaceAtmos).atmosphere=el.value;persist();render()});document.querySelectorAll('[data-enter-space]').forEach(b=>b.onclick=()=>{activeSpace=b.dataset.enterSpace;render()});document.querySelectorAll('[data-open-entity]').forEach(b=>b.onclick=()=>{tab='Entities';selected=b.dataset.openEntity;render()})}
function collection(){return tab==='Journal'?'journal':tab==='Systems'?'systems':'entities'}
function bind(){
const activePanels=()=>layoutTarget==='entity'?state.entities.find(x=>x.id===selected)?.layout:state.layouts.find(x=>x.id===layoutSelection)?.panels;
const editEntity=()=>state.entities.find(x=>x.id===selected);
const updatePanels=(fn)=>{let p=activePanels();if(!p)return;fn(p);persist();render()};
document.querySelector('#layoutMode')?.addEventListener('change',ev=>{let e=editEntity();e.layoutMode=ev.target.value;if(e.layoutMode==='custom'&&!e.layout?.length)e.layout=structuredClone(resolveLayout({...e,layoutMode:'inherit'},state));persist();render()});
document.querySelector('#entityLayout')?.addEventListener('change',ev=>{editEntity().layoutId=ev.target.value;persist();render()});
document.querySelector('#editEntityLayout')?.addEventListener('click',()=>{let e=editEntity();if(e.layoutMode!=='custom'||!e.layout?.length)e.layout=structuredClone(resolveLayout({...e,layoutMode:'inherit'},state));e.layoutMode='custom';layoutTarget='entity';tab='Layouts';persist();render()});
document.querySelector('#saveEntityLayout')?.addEventListener('click',()=>{let e=editEntity(),name=prompt('Name this reusable layout',e.name+' layout');if(!name?.trim())return;let id=uid();state.layouts.push({id,name:name.trim(),panels:structuredClone(resolveLayout(e,state))});e.layoutId=id;e.layoutMode='inherit';layoutSelection=id;persist();render()});
document.querySelector('#createLayout')?.addEventListener('click',()=>{let name=document.querySelector('#newLayoutName').value.trim();if(!name)return;let id=uid();state.layouts.push({id,name,panels:defaultLayout()});layoutTarget='preset';layoutSelection=id;persist();render()});
document.querySelector('#layoutTarget')?.addEventListener('change',ev=>{layoutTarget=ev.target.value;if(layoutTarget==='entity'){let e=editEntity()||state.entities[0];if(e){selected=e.id;if(!e.layout?.length)e.layout=structuredClone(resolveLayout(e,state));e.layoutMode='custom';persist()}}render()});
document.querySelector('#layoutSelection')?.addEventListener('change',ev=>{layoutSelection=ev.target.value;render()});
document.querySelector('#layoutEntity')?.addEventListener('change',ev=>{selected=ev.target.value;let e=editEntity();if(!e.layout?.length)e.layout=structuredClone(resolveLayout(e,state));e.layoutMode='custom';persist();render()});
document.querySelectorAll('[data-panel-up],[data-panel-down]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.panelUp??b.dataset.panelDown),j=i+(b.hasAttribute('data-panel-up')?-1:1);updatePanels(p=>{if(j>=0&&j<p.length)[p[i],p[j]]=[p[j],p[i]]})});
document.querySelectorAll('[data-panel-delete]').forEach(b=>b.onclick=()=>updatePanels(p=>p.splice(+b.dataset.panelDelete,1)));
document.querySelectorAll('[data-panel-width]').forEach(el=>el.addEventListener('change',()=>updatePanels(p=>p[+el.dataset.panelWidth].width=el.value)));
document.querySelectorAll('[data-panel-title],[data-panel-type],[data-panel-content]').forEach(el=>el.addEventListener('change',()=>{let key=el.hasAttribute('data-panel-title')?'title':el.hasAttribute('data-panel-type')?'type':'content';let i=Number(el.dataset.panelTitle??el.dataset.panelType??el.dataset.panelContent);updatePanels(p=>p[i][key]=el.value)}));
let touchPanel=null;document.querySelectorAll('.drag-handle').forEach(handle=>{handle.setAttribute('role','button');handle.setAttribute('aria-label','Hold and drag to reorder panel');handle.style.touchAction='none';handle.addEventListener('pointerdown',ev=>{if(ev.pointerType==='mouse')return;const el=handle.closest('[data-sort-panel]');touchPanel={from:Number(el.dataset.sortPanel),id:ev.pointerId};handle.setPointerCapture(ev.pointerId)});handle.addEventListener('pointerup',ev=>{if(!touchPanel||touchPanel.id!==ev.pointerId)return;const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-sort-panel]');if(target){const to=Number(target.dataset.sortPanel),from=touchPanel.from;if(from!==to)updatePanels(p=>{const [moved]=p.splice(from,1);p.splice(to,0,moved)})}touchPanel=null});handle.addEventListener('pointercancel',()=>touchPanel=null)});let draggedPanel=null;document.querySelectorAll('[data-sort-panel]').forEach(el=>{el.addEventListener('dragstart',ev=>{draggedPanel=Number(el.dataset.sortPanel);ev.dataTransfer.effectAllowed='move'});el.addEventListener('dragover',ev=>ev.preventDefault());el.addEventListener('drop',ev=>{ev.preventDefault();let target=Number(el.dataset.sortPanel);if(draggedPanel===null||draggedPanel===target)return;updatePanels(p=>{const [moved]=p.splice(draggedPanel,1);p.splice(target,0,moved)});draggedPanel=null})});
document.querySelector('#addPanel')?.addEventListener('click',()=>{let type=document.querySelector('#newPanelType').value;updatePanels(p=>p.push({id:uid(),type,title:type[0].toUpperCase()+type.slice(1),content:''}))});
document.querySelector('#deleteLayout')?.addEventListener('click',()=>{if(!confirm('Delete this reusable layout? Entities will use the default layout.'))return;state.layouts=state.layouts.filter(x=>x.id!==layoutSelection);state.entities.forEach(e=>{if(e.layoutId===layoutSelection)e.layoutId=''});layoutSelection=null;persist();render()});

 document.querySelector('#addMaster')?.addEventListener('click',()=>{let name=document.querySelector('#masterName').value.trim();if(!name)return;state.masters.push({id:uid(),name,tabs:['Overview'],traits:{}});persist();render()});
 document.querySelectorAll('[data-remove-master]').forEach(b=>b.onclick=()=>{if(!confirm('Delete template? Entities keep their own overrides.'))return;state.masters=state.masters.filter(m=>m.id!==b.dataset.removeMaster);persist();render()});
 document.querySelectorAll('[data-field^="masterName:"]').forEach(el=>el.oninput=()=>{state.masters.find(m=>m.id===el.dataset.field.split(':')[1]).name=el.value;persist()});
 document.querySelectorAll('[data-add-tab]').forEach(b=>b.onclick=()=>{let m=state.masters.find(x=>x.id===b.dataset.addTab),v=document.querySelector(`[data-tab-name="${m.id}"]`).value.trim();if(v&&!m.tabs.includes(v))m.tabs.push(v);persist();render()});
 document.querySelectorAll('[data-master-tab]').forEach(el=>el.onchange=()=>{let m=state.masters.find(x=>x.id===el.dataset.masterTab);m.tabs[+el.dataset.index]=el.value.trim()||'Untitled';persist();render()});
 document.querySelectorAll('[data-drop-tab]').forEach(b=>b.onclick=()=>{state.masters.find(x=>x.id===b.dataset.dropTab).tabs.splice(+b.dataset.index,1);persist();render()});
 document.querySelectorAll('[data-add-master-trait]').forEach(b=>b.onclick=()=>{let m=state.masters.find(x=>x.id===b.dataset.addMasterTrait),v=document.querySelector(`[data-master-key="${m.id}"]`).value.trim();if(v&&!Object.hasOwn(m.traits,v))m.traits[v]='';persist();render()});
 document.querySelectorAll('[data-master-trait]').forEach(el=>el.oninput=()=>{state.masters.find(x=>x.id===el.dataset.masterTrait).traits[el.dataset.traitKey]=el.value;persist()});
 document.querySelectorAll('[data-drop-master-trait]').forEach(b=>b.onclick=()=>{delete state.masters.find(x=>x.id===b.dataset.dropMasterTrait).traits[b.dataset.traitKey];persist();render()});
 document.querySelector('#entityMaster')?.addEventListener('change',e=>{state.entities.find(x=>x.id===selected).masterId=e.target.value;persist();render()});
 document.querySelectorAll('[data-inherited]').forEach(el=>el.oninput=()=>{state.entities.find(x=>x.id===selected).traits[el.dataset.inherited]=el.value;persist()});
 document.querySelectorAll('[data-clear-inherited]').forEach(b=>b.onclick=()=>{delete state.entities.find(x=>x.id===selected).traits[b.dataset.clearInherited];persist();render()});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;menuOpen=false;selected=null;filter='';render()});document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;render()});document.querySelector('#filter')?.addEventListener('input',e=>{filter=e.target.value;let start=e.target.selectionStart;render();document.querySelector('#filter')?.focus();document.querySelector('#filter')?.setSelectionRange(start,start)});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{let type=b.dataset.add;let id=uid();if(type==='Journal')state.journal.push({id,title:'Untitled note',body:'',folder:'',images:[],spaceId:'root'});else if(type==='Layout')state.layouts.push({id,name:'Untitled layout',panels:defaultPanels(),appearance:{}});else if(type==='System')state.systems.push({id,name:'Untitled system',kind:'Custom',steps:[],spaceId:'root'});else state.entities.push({id,name:'New '+type,kind:type==='Creature'?'Creature':'Character',description:'',traits:{},appearance:{own:false},spaceId:'root'});selected=id;persist();render()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this record?'))return;let c=b.dataset.delete==='journal'?'journal':b.dataset.delete==='system'?'systems':'entities';state[c]=state[c].filter(x=>x.id!==selected);if(c==='entities')state.links=state.links.filter(l=>l.from!==selected&&l.to!==selected);selected=null;persist();render()});document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener(el.tagName==='SELECT'?'change':'input',()=>{let obj=state[collection()].find(x=>x.id===selected);if(!obj)return;let k=el.dataset.field;if(k==='appearanceFont')obj.appearance.font=el.value;else if(k==='tags')obj.tags=el.value.split(',').map(x=>x.trim()).filter(Boolean);else obj[k]=el.value;persist();if(k==='body')references();if(k==='body'||k==='description')refreshLinkPreview()}));document.querySelectorAll('[data-trait]').forEach(el=>el.addEventListener('input',()=>{state.entities.find(x=>x.id===selected).traits[el.dataset.trait]=el.value;persist()}));document.querySelector('#addTrait')?.addEventListener('click',()=>{let k=document.querySelector('#traitName').value.trim();if(!k)return;state.entities.find(x=>x.id===selected).traits[k]='';persist();render()});document.querySelector('#entityBackground')?.addEventListener('change',ev=>{state.entities.find(x=>x.id===selected).appearance.backgroundImage=ev.target.value;persist();render()});document.querySelector('#ownTheme')?.addEventListener('change',e=>{state.entities.find(x=>x.id===selected).appearance.own=e.target.checked;persist();render()});document.querySelectorAll('[data-appearance]').forEach(el=>el.oninput=()=>{state.entities.find(x=>x.id===selected).appearance[el.dataset.appearance]=el.value;persist();render()});document.querySelector('#newSchema')?.addEventListener('click',()=>{let name=document.querySelector('#schemaName').value.trim();if(!name)return;state.schemas.push({id:uid(),name,fields:[],fieldTypes:{}});persist();render()});document.querySelectorAll('[data-add-field]').forEach(b=>b.onclick=()=>{let el=document.querySelector(`[data-new-field="${b.dataset.addField}"]`),name=el.value.trim(),s=state.schemas.find(x=>x.id===b.dataset.addField);if(name&&!s.fields.includes(name))s.fields.push(name);persist();render()});document.querySelectorAll('[data-remove-field]').forEach(b=>b.onclick=()=>{let s=state.schemas.find(x=>x.id===b.dataset.removeField);s.fields=s.fields.filter(x=>x!==b.dataset.name);persist();render()});document.querySelectorAll('[data-type]').forEach(el=>el.onchange=()=>{state.schemas.find(x=>x.id===el.dataset.type).fieldTypes[el.dataset.name]=el.value;persist()});document.querySelector('#captureSave')?.addEventListener('click',()=>{let body=document.querySelector('#capture').value.trim();if(!body)return;let id=uid();state.journal.push({id,title:body.slice(0,48),body,folder:'Inbox',images:[],spaceId:'root'});tab='Journal';selected=id;persist();render()});document.querySelector('#legacyImageInput')?.addEventListener('change',async e=>{let f=e.target.files[0];if(!f)return;if(f.size>300000)return alert('Choose an image smaller than 300 KB');let data=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)});state.journal.find(x=>x.id===selected).images.push({name:f.name,data});persist();render()});document.querySelectorAll('[data-remove-image]').forEach(b=>b.onclick=()=>{state.journal.find(x=>x.id===selected).images.splice(+b.dataset.removeImage,1);persist();render()});document.querySelector('#addStep')?.addEventListener('click',()=>{state.systems.find(x=>x.id===selected).steps.push('New state');persist();render()});document.querySelectorAll('[data-step]').forEach(el=>el.oninput=()=>{state.systems.find(x=>x.id===selected).steps[+el.dataset.step]=el.value;persist()});document.querySelectorAll('[data-remove-step]').forEach(b=>b.onclick=()=>{state.systems.find(x=>x.id===selected).steps.splice(+b.dataset.removeStep,1);persist();render()});document.querySelector('#addLink')?.addEventListener('click',()=>{let from=document.querySelector('#linkFrom').value,to=document.querySelector('#linkTo').value;if(!from||!to)return;state.links.push({id:uid(),from,to,kind:document.querySelector('#linkKind').value});persist();render()});document.querySelectorAll('[data-unlink]').forEach(b=>b.onclick=()=>{state.links=state.links.filter(x=>x.id!==b.dataset.unlink);persist();render()});bindDrag();document.querySelector('#addSpace')?.addEventListener('click',()=>{let name=document.querySelector('#spaceName').value.trim();if(!name)return;state.spaces.push({id:uid(),name,parent:'root'});persist();render()});document.querySelectorAll('[data-space-name]').forEach(el=>el.oninput=()=>{state.spaces.find(x=>x.id===el.dataset.spaceName).name=el.value;persist()});document.querySelectorAll('[data-space-parent]').forEach(el=>el.onchange=()=>{state.spaces.find(x=>x.id===el.dataset.spaceParent).parent=el.value;persist();render()});document.querySelectorAll('[data-remove-space]').forEach(b=>b.onclick=()=>{if(!confirm('Delete universe? Its contents move to Main Universe.'))return;let id=b.dataset.removeSpace;state.spaces=state.spaces.filter(x=>x.id!==id);state.spaces.forEach(s=>{if(s.parent===id)s.parent='root'});for(const c of [state.entities,state.journal,state.systems])c.forEach(x=>{if(x.spaceId===id)x.spaceId='root'});persist();render()});document.querySelectorAll('[data-theme]').forEach(el=>el.oninput=()=>{state.theme[el.dataset.theme]=el.value;persist();theme()});if(tab==='Themes')document.querySelector('[data-field="font"]')?.addEventListener('change',e=>{state.theme.font=e.target.value;persist();theme()});document.querySelector('#savePreset')?.addEventListener('click',()=>{let name=document.querySelector('#presetName').value.trim();if(!name)return;state.presets.push({id:uid(),name,...state.theme});persist();render()});document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{let p=state.presets.find(x=>x.id===b.dataset.preset);for(const k of Object.keys(state.theme))state.theme[k]=p[k]||state.theme[k];persist();render()});document.querySelectorAll('[data-delete-preset]').forEach(b=>b.onclick=()=>{state.presets=state.presets.filter(x=>x.id!==b.dataset.deletePreset);persist();render()});document.querySelector('#export')?.addEventListener('click',()=>download(state));document.querySelector('#quickExport').onclick=()=>download(state);document.querySelector('#import')?.addEventListener('change',async e=>{let f=e.target.files[0];if(!f)return;try{let obj=JSON.parse(await f.text());if(!obj||!Array.isArray(obj.entities)||!Array.isArray(obj.journal))throw Error('Not an Atlas world');if(!confirm('Replace the current world with this file? Export a backup first.'))return;state=normalize(obj);persist();tab='Home';selected=null;render()}catch(err){alert('Import failed: '+err.message)}});document.querySelector('#reset')?.addEventListener('click',()=>{if(!confirm('Erase the current world? Export a backup first.'))return;state=blank();persist();tab='Home';render()})}
function references(){let j=state.journal.find(x=>x.id===selected),target=document.querySelector('#references');if(!j||!target)return;let names=[...j.body.matchAll(/\[\[([^\]]+)\]\]/g)].map(m=>m[1]);target.innerHTML=names.length?`<p class="hint">Linked references: ${names.map(n=>{let e=state.entities.find(x=>x.name.toLowerCase()===n.toLowerCase());return e?`<button data-reference="${e.id}">${esc(n)}</button>`:`<span class="tag">${esc(n)} (unresolved)</span>`}).join(' ')}</p>`:'';target.querySelectorAll('[data-reference]').forEach(b=>b.onclick=()=>{tab='Entities';selected=b.dataset.reference;render()})}
function applyNexusView(){const w=document.querySelector('#nexusWorld');if(!w)return;w.style.transform=`translate(${nexusPan.x}px,${nexusPan.y}px) scale(${nexusZoom})`;const o=document.querySelector('#zoomLevel');if(o)o.textContent=Math.round(nexusZoom*100)+'%';}
function setNexusZoom(z,cx,cy){const c=document.querySelector('#canvas');if(!c)return;const old=nexusZoom;z=Math.max(.35,Math.min(2.5,z));cx??=c.clientWidth/2;cy??=c.clientHeight/2;nexusPan.x=cx-(cx-nexusPan.x)*z/old;nexusPan.y=cy-(cy-nexusPan.y)*z/old;nexusZoom=z;applyNexusView()}
function drawEdges(){const svg=document.querySelector('#edges'),world=document.querySelector('#nexusWorld');if(!svg||!world)return;svg.setAttribute('viewBox','0 0 1600 1200');svg.innerHTML=state.links.map(l=>{const a=[...world.querySelectorAll('[data-node]')].find(n=>n.dataset.node===l.from),b=[...world.querySelectorAll('[data-node]')].find(n=>n.dataset.node===l.to);if(!a||!b)return '';const x1=a.offsetLeft+65,y1=a.offsetTop+25,x2=b.offsetLeft+65,y2=b.offsetTop+25;return `<line class="nexus-link ${esc(l.kind)}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="var(--accent)" stroke-width="2" opacity=".75"/><text x="${(x1+x2)/2}" y="${(y1+y2)/2-5}" fill="var(--ink)" font-size="11">${esc(l.kind)}</text>`}).join('');applyNexusView()}
function bindDrag(){const c=document.querySelector('#canvas');if(!c)return;const pointers=new Map();let panStart=null,pinch=null;const distance=()=>{const a=[...pointers.values()];return Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)};
c.addEventListener('pointerdown',e=>{if(e.target.closest('.node'))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});c.setPointerCapture(e.pointerId);if(pointers.size===1)panStart={clientX:e.clientX,clientY:e.clientY,panX:nexusPan.x,panY:nexusPan.y};if(pointers.size===2){pinch={distance:distance(),zoom:nexusZoom};panStart=null}});
c.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&pinch){const r=c.getBoundingClientRect();const pts=[...pointers.values()];setNexusZoom(pinch.zoom*distance()/pinch.distance,(pts[0].x+pts[1].x)/2-r.left,(pts[0].y+pts[1].y)/2-r.top)}else if(panStart&&pointers.size===1){nexusPan={x:panStart.panX+e.clientX-panStart.clientX,y:panStart.panY+e.clientY-panStart.clientY};applyNexusView()}});
const end=e=>{pointers.delete(e.pointerId);panStart=null;pinch=null};c.addEventListener('pointerup',end);c.addEventListener('pointercancel',end);
c.addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();const r=c.getBoundingClientRect();setNexusZoom(nexusZoom*(e.deltaY>0?.9:1.1),e.clientX-r.left,e.clientY-r.top)},{passive:false});
document.querySelector('#zoomIn')?.addEventListener('click',()=>setNexusZoom(nexusZoom*1.2));document.querySelector('#zoomOut')?.addEventListener('click',()=>setNexusZoom(nexusZoom/1.2));document.querySelector('#zoomReset')?.addEventListener('click',()=>{nexusZoom=1;nexusPan={x:0,y:0};applyNexusView()});
c.querySelectorAll('[data-node]').forEach(el=>{let start=null;el.addEventListener('pointerdown',e=>{if(e.button!==0||pointers.size)return;e.stopPropagation();start={x:e.clientX,y:e.clientY,left:el.offsetLeft,top:el.offsetTop};el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(!start)return;el.style.left=Math.max(0,Math.min(1600-el.offsetWidth,start.left+(e.clientX-start.x)/nexusZoom))+'px';el.style.top=Math.max(0,Math.min(1200-el.offsetHeight,start.top+(e.clientY-start.y)/nexusZoom))+'px';drawEdges()});const finish=()=>{if(!start)return;const obj=state.entities.find(x=>x.id===el.dataset.node);if(obj){obj.x=el.offsetLeft;obj.y=el.offsetTop;persist()}start=null};el.addEventListener('pointerup',finish);el.addEventListener('pointercancel',finish)});applyNexusView()}

// Local IndexedDB storage is per origin and installation. Export/import remains the transfer method.

projectList=await listProjects();

// The media library is a separate binary store, scoped to the active project.
let mediaCache=[],mediaUrls=[],mediaDestination=null;
function mediaPage(){return `<h1>Media Library</h1><p class="hint">Upload from iPhone Photos, Camera, or Files. Images are optimized and stored offline in IndexedDB. Use the image on any journal or entity in this project.</p><button id="mediaPageAdd" class="primary">＋ Add images</button><div id="mediaPageGrid" class="media-grid"></div><p class="hint">Export a media-inclusive backup from Data to transfer images between devices.</p>`}
function mediaDialog(){let dlg=document.getElementById('atlasMediaDialog');if(dlg)return dlg;dlg=document.createElement('div');dlg.id='atlasMediaDialog';dlg.className='media-modal';dlg.hidden=true;dlg.innerHTML=`<div class="media-sheet" role="dialog" aria-modal="true" aria-label="Atlas image manager"><div class="row"><h2 class="grow">Add an image</h2><button id="mediaClose" aria-label="Close image picker">✕</button></div><div class="media-actions"><button id="mediaPhotos">▧ Photo Library</button><button id="mediaCamera">◎ Take Photo</button><button id="mediaFiles">▤ Browse Files</button><button id="mediaURL">↗ Image URL</button></div><input type="file" id="mediaPhotosInput" accept="image/*" multiple><input type="file" id="mediaCameraInput" accept="image/*" capture="environment"><input type="file" id="mediaFilesInput" accept="image/*,.heic,.heif" multiple><p id="mediaFeedback" role="status" aria-live="polite"></p><h3>Project media library</h3><div id="mediaDialogGrid" class="media-grid"></div></div>`;document.body.append(dlg);dlg.querySelector('#mediaClose').onclick=()=>{dlg.hidden=true};dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.hidden=true});for(const [btn,input] of [['mediaPhotos','mediaPhotosInput'],['mediaCamera','mediaCameraInput'],['mediaFiles','mediaFilesInput']]){dlg.querySelector('#'+btn).onclick=()=>dlg.querySelector('#'+input).click();dlg.querySelector('#'+input).onchange=async e=>{await uploadFiles(e.target.files);e.target.value=''}}dlg.querySelector('#mediaURL').onclick=()=>{const url=prompt('Paste a direct HTTPS image URL');if(!url)return;if(!/^https:\/\//i.test(url))return alert('Use an HTTPS URL');if(mediaDestination?.kind==='entity'){const e=state.entities.find(x=>x.id===mediaDestination.id);if(e){e.appearance ||= {};e.appearance.backgroundImage=url;persist()}}else if(mediaDestination?.kind==='journal'){const j=state.journal.find(x=>x.id===mediaDestination.id);if(j){j.images ||= [];j.images.push({name:'External image',data:url});persist()}}else{state.dashboard.cover=url;persist()}dlg.hidden=true;render()};return dlg}
async function uploadFiles(files){const feedback=document.getElementById('mediaFeedback');if(!files?.length)return;feedback.textContent='Optimizing and saving photos…';try{for(const f of files){await addMedia(currentProjectId(),f)}feedback.textContent='Photos saved to this device.';await refreshMedia()}catch(e){feedback.textContent='Could not add image: '+e.message}}
function mediaImage(id){const entry=mediaCache.find(x=>x.id===id);return entry?.url||''}
async function refreshMedia(){mediaUrls.forEach(u=>URL.revokeObjectURL(u));mediaUrls=[];const project=currentProjectId();const items=await listMedia(project);const records=await Promise.all(items.map(async item=>{const full=await getMedia(project,item.id);const url=URL.createObjectURL(full.blob);mediaUrls.push(url);return {...item,url}}));mediaCache=records;const grid=document.getElementById('mediaDialogGrid');if(grid)grid.innerHTML=records.map(x=>`<div class="media-tile"><img src="${x.url}" alt="${esc(x.name)}"><button data-use-media="${x.id}">Use image</button></div>`).join('')||'<p>No images yet.</p>';const page=document.getElementById('mediaPageGrid');if(page)page.innerHTML=records.map(x=>`<div class="media-tile"><img src="${x.url}" alt="${esc(x.name)}"><small>${esc(x.name)}</small><button data-delete-media="${x.id}">Delete</button></div>`).join('');for(const kind of ['journal','entity']){const el=document.getElementById(kind+'Media');const rec=kind==='journal'?state.journal.find(x=>x.id===selected):state.entities.find(x=>x.id===selected);if(el){el.classList.add('atlas-gallery');el.innerHTML=(rec?.mediaIds||[]).map((id,i)=>{const x=records.find(a=>a.id===id);if(!x)return '';const m=rec.mediaPresentation?.[id]||{};const zoom=Math.max(1,Math.min(3,Number(m.zoom)||1));const px=Math.max(0,Math.min(100,Number(m.x)??50)),py=Math.max(0,Math.min(100,Number(m.y)??50));return `<figure class="atlas-gallery-card"><div class="atlas-gallery-frame" style="aspect-ratio:${m.ratio==='1:1'?'1':m.ratio==='16:9'?'16/9':m.ratio==='3:4'?'3/4':'4/3'}"><img src="${x.url}" alt="${esc(m.caption||x.name)}" style="object-position:${px}% ${py}%;transform:scale(${zoom})"></div><figcaption>${esc(m.caption||x.name)}</figcaption><div class="atlas-gallery-controls"><button type="button" data-edit-media="${esc(id)}" data-edit-kind="${kind}">Edit</button><button type="button" data-move-media="${esc(id)}" data-move-dir="-1" aria-label="Move image earlier">←</button><button type="button" data-move-media="${esc(id)}" data-move-dir="1" aria-label="Move image later">→</button><button type="button" data-unattach="${esc(id)}">Remove</button></div></figure>`}).join('');el.querySelectorAll('[data-unattach]').forEach(b=>b.onclick=()=>{rec.mediaIds=rec.mediaIds.filter(id=>id!==b.dataset.unattach);persist();refreshMedia()});el.querySelectorAll('[data-move-media]').forEach(b=>b.onclick=()=>{const i=rec.mediaIds.indexOf(b.dataset.moveMedia),j=i+Number(b.dataset.moveDir);if(j<0||j>=rec.mediaIds.length)return;[rec.mediaIds[i],rec.mediaIds[j]]=[rec.mediaIds[j],rec.mediaIds[i]];persist();refreshMedia()});el.querySelectorAll('[data-edit-media]').forEach(b=>b.onclick=()=>openImageEditor(rec,b.dataset.editMedia))}}document.querySelectorAll('[data-use-media]').forEach(b=>b.onclick=()=>{const d=mediaDestination;if(d?.kind==='entity'||d?.kind==='journal'){const rec=state[d.kind==='entity'?'entities':'journal'].find(x=>x.id===d.id);if(rec){rec.mediaIds||=[];if(!rec.mediaIds.includes(b.dataset.useMedia))rec.mediaIds.push(b.dataset.useMedia);persist()}}else{const item=records.find(x=>x.id===b.dataset.useMedia);if(item)alert('Open a journal or entity to attach this image.')}document.getElementById('atlasMediaDialog').hidden=true;refreshMedia()});document.querySelectorAll('[data-delete-media]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this image from the project library?'))return;await removeMedia(project,b.dataset.deleteMedia);for(const rec of [...state.entities,...state.journal])rec.mediaIds=(rec.mediaIds||[]).filter(id=>id!==b.dataset.deleteMedia);persist();refreshMedia()})}
function openImageEditor(rec,id){const item=mediaCache.find(x=>x.id===id);if(!item)return;rec.mediaPresentation||={};const original=rec.mediaPresentation[id]||{};const m={caption:original.caption||'',ratio:original.ratio||'4:3',zoom:original.zoom||1,x:original.x??50,y:original.y??50};let dlg=document.getElementById('atlasImageEditor');if(!dlg){dlg=document.createElement('div');dlg.id='atlasImageEditor';dlg.className='media-modal';document.body.append(dlg)}dlg.hidden=false;dlg.innerHTML=`<div class="media-sheet" role="dialog" aria-modal="true" aria-label="Edit image"><div class="row"><h2 class="grow">Image editor</h2><button type="button" id="imageEditorClose">✕</button></div><div class="image-editor-preview"><img src="${item.url}" alt="Image preview"></div><label>Caption<input id="imageCaption" maxlength="300" value="${esc(m.caption)}" placeholder="Describe this image"></label><label>Frame shape<select id="imageRatio"><option value="4:3">Landscape 4:3</option><option value="1:1">Square</option><option value="16:9">Wide 16:9</option><option value="3:4">Portrait 3:4</option></select></label><label>Zoom <output id="imageZoomValue"></output><input type="range" id="imageZoom" min="1" max="3" step="0.05" value="${m.zoom}"></label><label>Horizontal position<input type="range" id="imageX" min="0" max="100" value="${m.x}"></label><label>Vertical position<input type="range" id="imageY" min="0" max="100" value="${m.y}"></label><p class="hint">Cropping is non-destructive: the original photo stays in your media library.</p><div class="row"><button id="imageEditorCancel">Cancel</button><button class="primary" id="imageEditorSave">Save image layout</button></div></div>`;const q=id=>dlg.querySelector('#'+id);q('imageRatio').value=m.ratio;const update=()=>{const img=q('imageZoom').value;const ratio=q('imageRatio').value;const preview=dlg.querySelector('.image-editor-preview');preview.style.aspectRatio=ratio==='1:1'?'1':ratio==='16:9'?'16/9':ratio==='3:4'?'3/4':'4/3';const pic=preview.querySelector('img');pic.style.transform=`scale(${img})`;pic.style.objectPosition=`${q('imageX').value}% ${q('imageY').value}%`;q('imageZoomValue').textContent=Number(img).toFixed(2)+'×'};['imageRatio','imageZoom','imageX','imageY'].forEach(k=>q(k).addEventListener('input',update));update();const close=()=>{dlg.hidden=true};q('imageEditorClose').onclick=close;q('imageEditorCancel').onclick=close;q('imageEditorSave').onclick=()=>{rec.mediaPresentation[id]={caption:q('imageCaption').value,ratio:q('imageRatio').value,zoom:Number(q('imageZoom').value),x:Number(q('imageX').value),y:Number(q('imageY').value)};persist();close();refreshMedia()}}
function openMedia(kind,id){mediaDestination={kind,id};mediaDialog().hidden=false;refreshMedia().catch(e=>alert('Media storage unavailable: '+e.message))}
function bindMedia(){document.querySelector('#openMedia')?.addEventListener('click',()=>openMedia(tab==='Journal'?'journal':tab==='Entities'||tab==='Bestiary'?'entity':'library',selected));document.querySelectorAll('[data-media-for]').forEach(b=>b.onclick=()=>openMedia(b.dataset.mediaFor,selected));document.querySelector('#mediaPageAdd')?.addEventListener('click',()=>openMedia('library',null));refreshMedia().catch(console.error)}
async function mediaBackup(){try{await flushSaves();const images=await exportMedia(currentProjectId());const blob=new Blob([JSON.stringify({format:'atlas-media-backup-1',world:state,images})],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='atlas-world-with-images.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}catch(e){alert('Backup failed: '+e.message)}}
async function importMediaBackup(file){try{const payload=JSON.parse(await file.text());if(payload.format!=='atlas-media-backup-1'||!Array.isArray(payload.images)||!payload.world)throw Error('Not an Atlas media backup');if(!confirm('Replace current world AND its media with this backup? Export a backup first.'))return;await clearMedia(currentProjectId());await importMedia(currentProjectId(),payload.images);state=normalize(payload.world);await savePersistent(state);tab='Home';selected=null;render()}catch(e){alert('Import failed: '+e.message)}}
const oldData=data;data=function(){return oldData()+`<div class="card"><h2>Images included in backup</h2><p class="hint">Standard JSON export does not contain separately stored photos. Use this option to move photos to another device.</p><button id="exportWithMedia" class="primary">Export world + images</button><label>Import world + images<input id="importWithMedia" type="file" accept="application/json,.json"></label></div>`};
const oldBind=bind;bind=function(){oldBind();document.querySelector('#exportWithMedia')?.addEventListener('click',mediaBackup);document.querySelector('#importWithMedia')?.addEventListener('change',e=>{if(e.target.files[0])importMediaBackup(e.target.files[0])})};

// Global command search: searches local project data only; no server or tracking.
let atlasCommandReturnFocus=null,atlasCommandIndex=0,atlasCommandMatches=[];
function atlasSearchItems(){return [
 ...tabs.map(name=>({kind:'section',name,tab:name,id:null})),
 ...(state.entities||[]).map(x=>({kind:'entity',name:x.name||'Untitled',tab:'Entities',id:x.id})),
 ...(state.journal||[]).map(x=>({kind:'journal',name:x.title||'Untitled',tab:'Journal',id:x.id})),
 ...(state.systems||[]).map(x=>({kind:'system',name:x.name||'Untitled',tab:'Systems',id:x.id})),
 ...(state.spaces||[]).map(x=>({kind:'universe',name:x.name||'Untitled',tab:'Universes',id:x.id}))
]}
function atlasCloseSearch(){const modal=document.getElementById('atlasCommandOverlay');if(modal)modal.hidden=true;atlasCommandReturnFocus?.focus?.()}
function atlasOpenResult(item){if(!item)return;tab=item.tab;selected=item.id;filter='';if(item.kind==='universe')activeSpace=item.id;menuOpen=false;atlasCloseSearch();render()}
function atlasUpdateSearch(){const field=document.getElementById('atlasCommandInput'),results=document.getElementById('atlasCommandResults');if(!field||!results)return;const query=field.value.trim().toLocaleLowerCase();atlasCommandMatches=atlasSearchItems().filter(x=>!query||x.name.toLocaleLowerCase().includes(query)||x.kind.includes(query)).slice(0,40);atlasCommandIndex=0;results.innerHTML=atlasCommandMatches.map((x,i)=>`<button type="button" class="atlas-command-result" data-search-result="${i}" aria-selected="${i===0}"><span>${esc(x.name)}</span><small>${esc(x.kind)}</small></button>`).join('')||'<div class="atlas-command-empty">No matches in this world.</div>';results.querySelectorAll('[data-search-result]').forEach(b=>b.onclick=()=>atlasOpenResult(atlasCommandMatches[Number(b.dataset.searchResult)]))}
function atlasOpenSearch(){atlasCommandReturnFocus=document.activeElement;let modal=document.getElementById('atlasCommandOverlay');if(!modal){modal=document.createElement('div');modal.id='atlasCommandOverlay';modal.className='atlas-command-overlay';modal.hidden=true;modal.innerHTML='<section class="atlas-command" role="dialog" aria-modal="true" aria-label="Search Atlas"><div class="atlas-command-head"><h2>Find in Atlas</h2><button type="button" id="atlasCommandClose" aria-label="Close search">✕</button></div><input id="atlasCommandInput" type="search" placeholder="Search characters, journals, systems…" autocomplete="off" aria-label="Search this world"><div class="atlas-command-results" id="atlasCommandResults"></div><p class="hint">Searches the current world on this device.</p></section>';document.body.append(modal);modal.addEventListener('click',e=>{if(e.target===modal)atlasCloseSearch()});modal.querySelector('#atlasCommandClose').onclick=atlasCloseSearch;modal.querySelector('#atlasCommandInput').addEventListener('input',atlasUpdateSearch);modal.querySelector('#atlasCommandInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();atlasOpenResult(atlasCommandMatches[atlasCommandIndex])}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();atlasCommandIndex=Math.max(0,Math.min(atlasCommandMatches.length-1,atlasCommandIndex+(e.key==='ArrowDown'?1:-1)));modal.querySelectorAll('[data-search-result]').forEach((b,i)=>b.setAttribute('aria-selected',String(i===atlasCommandIndex)));modal.querySelector(`[data-search-result="${atlasCommandIndex}"]`)?.scrollIntoView({block:'nearest'})}})}modal.hidden=false;const field=modal.querySelector('#atlasCommandInput');field.value='';atlasUpdateSearch();field.focus()}
document.addEventListener('click',e=>{if(e.target.closest('#atlasSearchOpen'))atlasOpenSearch()});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();atlasOpenSearch()}else if(e.key==='Escape'&&!document.getElementById('atlasCommandOverlay')?.hidden)atlasCloseSearch()});

// Start only after all features and media handlers have been registered.
// Previously this build never invoked render(), leaving #app empty.
try {
  render();
  refreshMedia().catch(error => console.warn('Media library unavailable:', error));
} catch (error) {
  console.error('Atlas failed to render:', error);
  window.atlasShowStartupError?.(error);
}
